#include <stdio.h>

double average(const int values[], int count) {
    int sum = 0;
    for (int i = 0; i < count; i++) {
        sum += values[i];
    }
    return (double)sum / count;
}

int main() {
    int numbers[] = {4, 8, 15, 16, 23};
    int count = sizeof(numbers) / sizeof(numbers[0]);
    printf("%.1f\n", average(numbers, count));
    return 0;
}
